    // status-cascade) silently missed the +1 BaseReplayCount bump.
    scan(state.player.hand.as_slice(), state.cards.as_slice());
    scan(state.player.draw.as_slice(), state.cards.as_slice());
    scan(state.player.discard.as_slice(), state.cards.as_slice());
